// === Tab: mySketch ===
function setup() {
	createCanvas(700, 500);
	background(111);
	angleMode(DEGREES)
	dudes = [];
	for (i = 250; i--;) {
		dudes.push({
			x: 50,
			y: height / 2,
			pAngle: 90,
			pColor: round(random(0, 360)),
			pA: random(0, TWO_PI),
			pB: random(-TWO_PI, TWO_PI) / 4,
			pC: random(0, TWO_PI),
			pShift: random(0, 8),
			pFC: 0,
			score: 0
		});
	}
	bestDude = dudes[0];
	noStroke()
	resets = 0
}

function draw() {
	noStroke()
	fill("#0001");
	xSum = 0;
	rect(0, 20, width, height);
	for (dude of dudes) {
		fill(`hsl(${dude.pColor},99%,50%)`);
		circle(dude.x, dude.y, 7);
		dude.x += sin(dude.pB * dude.pA+dude.pShift) + dude.pShift + sin(dude.pAngle + dude.pFC * dude.pB) * dude.pB
		dude.y += sin(dude.y/dude.pShift) + cos(dude.pAngle + dude.pFC * dude.pB + sin(dude.pB*dude.pA + dude.x/dude.pShift) * dude.pC)
		dude.pB
		dude.pFC += 1
		fill(`hsl(${360-dude.pColor},99%,50%)`);
		rect(300, 0, 20, 200)
		rect(300, 300, 20, 200)
		rect(400, 200, 20, 100)
		if (dude.x > 300 && dude.x < 320) {
			if (dude.y < 200 || dude.y > 300) {
				dude.x = 300;
			}
		}
		if (dude.x > 400 && dude.x < 420) {
			if (dude.y > 200 && dude.y < 300) {
				dude.x = 400
			}
		}
		xSum += dude.x 
	}
	if (frameCount % 777 == 0) {
		for (i of dudes) {
			if (i.score > bestDude.score) bestDude = i;
		}
		for (i of dudes) {
			i.x = 50;
			i.y = height / 2;
			i.score = 0;
			i.pAngle = 90
			i.pFC = 0
			i.pShift = (bestDude.pShift + i.pShift) / 2 + random(-1, 1) / 9
			i.pA = (bestDude.pA + i.pA) / 2 + random(-1, 1) / 9
			i.pB = (bestDude.pB + i.pB) / 2 + random(-1, 1) / 9
			i.pC = (bestDude.pC + i.pC) / 2 + random(-1, 1) / 9
			i.pColor = round((bestDude.pColor + i.pColor) / 2)
		}
		resets ++;
	}
	fill(`hsl(${(resets*40)%360},99%,50%)`)
	rect(100+xSum/dudes.length/3, resets*2, 7, 30)
	fill("#000")
	stroke("#0a0")
	rect(0,0,100,100)
	for(d in dudes) {
		fill("#00f")
		if(dudes[d].x<width-60) rect(dudes[d].x/width*100, d*100/dudes.length, 10, 100/dudes.length)
	}
}

